command:
$ErrorActionPreference='Stop'
git fetch origin --prune
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$expected=@(
'app/winui/MainWindow.xaml.cpp',
'app/winui/file_detail_controller.cpp',
'app/winui/file_list_state.h',
'app/winui/helper/FlyShellIsolationHelper.cpp',
'src/base/shell_assoc_type_core.cpp',
'src/base/shell_assoc_type_core.h',
'tests/winui/test_known_folder_artwork_contract.py'
)
$status=@(git status --porcelain)
Write-Output 'STATUS_BEFORE'
$status | ForEach-Object { Write-Output $_ }
$paths=@()
foreach($line in $status){
  if($line.Length -lt 4){throw "Unexpected status line: $line"}
  $p=$line.Substring(3)
  if($p.StartsWith('"')){throw "Quoted status path not expected: $line"}
  $paths+=$p
}
$unexpected=@($paths | Where-Object { $_ -notin $expected })
$missing=@($expected | Where-Object { $_ -notin $paths })
if($unexpected.Count -ne 0 -or $missing.Count -ne 0){
  Write-Output "UNEXPECTED=$($unexpected -join ',')"
  Write-Output "MISSING=$($missing -join ',')"
  throw 'Refusing to sync because dirty scope differs from the accepted Known Folder unit.'
}
foreach($p in $expected){
  $local=(git hash-object -- $p).Trim()
  $remote=(git rev-parse "origin/main:$p").Trim()
  Write-Output "HASH $p LOCAL=$local REMOTE=$remote"
  if($local -ne $remote){throw "Content mismatch against origin/main: $p"}
}
git stash push -u -m 'redundant-known-folder-main-sync'
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$after=@(git status --porcelain)
if($after.Count -ne 0){$after|ForEach-Object{Write-Output $_};throw 'Checkout not clean after fast-forward.'}
$stash=(git stash list -1).Trim()
Write-Output "STASH_TOP=$stash"
if($stash -notmatch 'redundant-known-folder-main-sync'){throw 'Expected safety stash not found.'}
git stash drop 'stash@{0}'
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
Write-Output 'SYNCED_HEAD'
git rev-parse HEAD
Write-Output 'SYNCED_STATUS'
git status --short
